import { render } from '@solidjs/web';
import { For } from 'solid-js';
import html from '@solidjs/html';
import { createTodos } from './model';

function App() {
  const { state, editTitle, add, update, remove } = createTodos();
  return html`<div>
    <h3>Simple Todos Example</h3>
    <input
      placeholder="enter todo and click +"
      value=${() => state.newTitle}
      onInput=${(event) => editTitle(event.currentTarget.value)}
    />
    <button onClick=${add}>+</button>
    <${For} each=${() => state.todos}
      >${(todo) =>
        html`<div>
          <input
            type="checkbox"
            checked=${() => todo.done}
            onChange=${(event) =>
              update(todo.id, { done: event.currentTarget.checked })}
          />
          <input
            value=${() => todo.title}
            onChange=${(event) =>
              update(todo.id, { title: event.currentTarget.value })}
          />
          <button onClick=${() => remove(todo.id)}>x</button>
        </div>`}<//
    >
  </div>`;
}

render(() => <App />, document.getElementById('app'));

import { createStore, createEffect, untrack } from 'solid-js';

export function createTodos() {
  const initial = untrack(() => {
    try {
      return (
        JSON.parse(localStorage.getItem('solid2-todos')) ?? {
          todos: [],
          newTitle: '',
          nextId: 0,
        }
      );
    } catch {
      return { todos: [], newTitle: '', nextId: 0 };
    }
  });
  const [state, setState] = createStore(initial);
  createEffect(
    () => JSON.stringify(state),
    (value) => localStorage.setItem('solid2-todos', value),
  );
  const editTitle = (value) =>
    setState((draft) => {
      draft.newTitle = value;
    });
  const add = () =>
    setState((draft) => {
      if (!draft.newTitle.trim()) return;
      draft.todos.push({
        id: ++draft.nextId,
        title: draft.newTitle,
        done: false,
      });
      draft.newTitle = '';
    });
  const update = (id, patch) =>
    setState((draft) => {
      const todo = draft.todos.find((todo) => todo.id === id);
      if (todo) Object.assign(todo, patch);
    });
  const remove = (id) =>
    setState((draft) => {
      const index = draft.todos.findIndex((todo) => todo.id === id);
      if (index >= 0) draft.todos.splice(index, 1);
    });
  return { state, editTitle, add, update, remove };
}
